/** The default lexicon: the course words (data/words.json, generated by the course package). */
import wordsFile from './data/words.json';
import { JaLexicon, type NameEntry, type WordEntry } from './lexicon';

export const COURSE_WORDS = wordsFile as WordEntry[];

let shared: JaLexicon | undefined;

/** The lexicon of the course words (built once), or a new one that also knows `names`. */
export function courseLexicon(names?: readonly NameEntry[]): JaLexicon {
  if (names && names.length > 0) return new JaLexicon(COURSE_WORDS, { names });
  shared ??= new JaLexicon(COURSE_WORDS);
  return shared;
}
